package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class UpperPracticalPlaceTest {
 @Test public void all20002PublicInventoriesOwnAnswersAndBlankRelationships(){Set<String> signatures=new HashSet<>();for(int c=0;c<2;c++)for(int n=0;n<=10000;n++){Question q=PracticalPlaceStories.makeUpper(c,n);assertTrue(signatures.add(q.signature()));q.answers=new String[]{"poison"};q.expression="poison";int[] v=PracticalPlaceStories.readUpper(q);assertNotNull(v);assertEquals(n,v[0]*1000+v[1]*100+v[2]*10+v[3]);assertTrue(new Checker().check(q,List.of(),List.of(""+n)).correct());assertEquals(Checker.Status.WRONG_ANSWER,new Checker().check(q,List.of(),List.of(""+(n+1))).status);HelpPlan p=HelpPlan.forQuestion(q);assertFalse(p.canTransfer());assertEquals(5,p.size());assertTrue(p.restore(null,q.id).entries.stream().allMatch(String::isEmpty));int[] a={v[0]*1000,v[1]*100,v[2]*10,v[3],n};for(int i=0;i<5;i++){assertTrue(p.step(i).accepts(""+a[i]));assertFalse(p.step(i).before.matches("(?s).*[0-9].*"));}assertTrue(q.choices.isEmpty());}assertEquals(20002,signatures.size());}
 @Test public void realGradeFourSupplyAndFullPublicHistoryOldest(){CurriculumLimits limits=GlobalCurriculum.limits("england-primary-2021-v1",PracticalPlaceStories.ID,4);List<String> recent=new ArrayList<>();Generator g=new Generator(new Random(144));boolean thousands=false;for(int i=0;i<300;i++){Question q=g.next(PracticalPlaceStories.ID,recent,false,limits);assertNotNull(PracticalPlaceStories.readUpper(q));assertFalse(recent.contains(q.signature()));recent.add(q.signature());thousands|=PracticalPlaceStories.readUpper(q)[4]>1000;}assertTrue(thousands);Map<String,Integer> full=new LinkedHashMap<>();for(int c=0;c<2;c++)for(int n=0;n<=10000;n++)full.put(PracticalPlaceStories.makeUpper(c,n).signature(),full.size());assertEquals(full.keySet().iterator().next(),PracticalPlaceStories.next(new Random(1),limits,full).signature());Learning.Profile profile=new Learning.Profile();GlobalCurriculum.chooseCountry(profile,"GB");GlobalCurriculum.choosePack(profile,"england-primary-2021-v1");assertTrue(GlobalCurriculum.pack(profile).inGrade(PracticalPlaceStories.ID,4));assertTrue(GlobalCurriculum.pack(profile).inGrade(PracticalPlaceStories.ID,3));assertFalse(GlobalCurriculum.pack(profile).inGrade(PracticalPlaceStories.ID,2));}
 @Test public void malformedInventoriesCannotUseHiddenAnswers(){for(String prompt:List.of(PracticalPlaceStories.makeUpper(0,10000).prompt.replace("낱개: 0","낱개: 1"),PracticalPlaceStories.makeUpper(0,9000).prompt.replace("큰 상자: 9","큰 상자: 11"),"스티커\n모두 몇 개인가요?")){Question q=PracticalPlaceStories.makeUpper(0,0);q.prompt=prompt;q.answers=new String[]{"0"};assertNull(PracticalPlaceStories.readUpper(q));assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("0")).status);}Question q=PracticalPlaceStories.makeUpper(1,10000);for(String s:List.of("","1e4","10,000","-10000","100000"))assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of(s)).status);}
}
